/**
 * server/src/ragRuntimeConfig.js
 *
 * Unified runtime configuration resolver for RAG chat and preview.
 *
 * Resolves retrieval/generation configuration from the persisted workflow
 * nodes (generated by Phase 8 workflowBuilder) for a given rag_app row.
 *
 * All chat paths (preview and public) must call this helper — it ensures
 * architect_plan.retrieval.top_k = VectorStore.params.top_k = runtime top_k.
 *
 * Legacy compatibility:
 *   Apps created before Phase 8 (no architect-generated nodes) fall back
 *   to documented defaults rather than hardcoded magic numbers inline.
 */

import { DEFAULT_CHAT_MODEL } from './openai.js';

// ─── Compatibility defaults ────────────────────────────────────────────────

const DEFAULTS = {
  top_k:              5,
  model:              DEFAULT_CHAT_MODEL,
  temperature:        0.7,
  grounding_required: false,
  response_style:     '',
};

/**
 * Resolve runtime configuration from a rag_app's persisted workflow nodes.
 *
 * @param {object} ragApp — row from rag_apps (must have .nodes already parsed)
 * @returns {{
 *   top_k: number,
 *   model: string,
 *   temperature: number,
 *   grounding_required: boolean,
 *   response_style: string,
 *   architect_version: number | null,
 * }}
 */
export function resolveRagRuntimeConfig(ragApp) {
  const nodes = Array.isArray(ragApp.nodes) ? ragApp.nodes : [];

  // ── Retrieval node (VectorStore) ──────────────────────────────────────────
  const retrievalNode = nodes.find(n => n.type === 'VectorStore');
  const top_k = typeof retrievalNode?.params?.top_k === 'number'
    ? retrievalNode.params.top_k
    : DEFAULTS.top_k;

  // ── Generation node (LLM) ────────────────────────────────────────────────
  const llmNode = nodes.find(n => n.type === 'LLM');
  const model            = llmNode?.params?.model              || DEFAULTS.model;
  const temperature      = typeof llmNode?.params?.temperature === 'number'
    ? llmNode.params.temperature
    : DEFAULTS.temperature;
  const grounding_required = typeof llmNode?.params?.grounding_required === 'boolean'
    ? llmNode.params.grounding_required
    : DEFAULTS.grounding_required;
  const response_style   = llmNode?.params?.response_style     || DEFAULTS.response_style;

  // ── Architect version (if available) ─────────────────────────────────────
  const architect_version = llmNode?.params?.architect_version ?? null;

  return { top_k, model, temperature, grounding_required, response_style, architect_version };
}
